    /* Create the ITS Visualiser <i>namespace</i> */
    window.its = window.its || {};
    window.its.visualiser = window.its.visualiser || {};
    /**
     * Set a Listener to intercept errors generated by the WDV Web UI
     * 
     *  - If there is a Browser Console: It will log the error there.
     *  - If WDV Common JS has initialised: It will display errors using<i><b>method</b>
     *    its.visualiser.common.ReportError()</i>. Otherwise, it will use
     *    <i><b>Alert()</b</i>
     *  
     * @note the following are the standard JavaScript Error Properties
     * @param {string} msg
     * @param {type} url
     * @param {type} lineNo
     * @param {type} columnNo
     * @param {type} error
     * @returns {Boolean}
     */
    window.onerror = function (msg, url, lineNo, columnNo, error) {
        var errorText = '';
        if (url.indexOf('turftrax') > 0) {
            errorText = "A JavaScript Error [" + msg + "] has occurred in:\n";
            errorText+= url + ", At Line: " + lineNo + ", Column: " + columnNo + ".\n";
            errorText+= "This may prevent the page from loading or working correctly\n";
            if (window.console) {
                console.log(errorText);
            }
            if (window.its.visualiser.common) {
                window.its.visualiser.common.ReportError(errorText);
            }
            else {
                alert(errorText);
            }
        }
        return false;
    };
    /* Create the WDV Common JS Object */
    window.its.visualiser.common = {
        descartes: 'WDV Common',
        logEnabled: null,
        errorHTML: '\n\
        <dl>\n\
            <dt>Sorry, but some required Resources could not be loaded. This may adversely affected the validity of the page content</dt>\n\
            <dd id="error-message" style="font-size:smaller;font-weight:normal;"></dd>\n\
            <dd>Performing a <i>forced reload (CTRL-F5)</i> may clear the issue</dd>\n\
            <dt>This Message will clear in <span id="error-countdown"></span> seconds or Click It to remove it. Thank you.</dt>\n\
        </dl>',
        errorCSS: 'position:absolute;top:0px;left:0px;width:100%;height:100%;margin:auto;z-index:999;background-color:white;color:red;font-size:14px;font-weight:bold;',
        errorMessages: null,
        codeBase: null,
        codeName: null,
        subDomain: null,
        useProtocol: null,
        useHost: null,
        errorTimeout: 5,
        errorTimer: null,
        errorCountdown: null,
        wdvSections: ['going-report-wdv', 'awt-report-wdv', 'weather-report-wdv','wdv-explained'],
        
        License: {
            inFrame: false,
            haveTTEMA: false,
            haveTTSVC: false,
            Init: function() {
                var that = window.its.visualiser.common.License;
                if (window.self !== window.top) {
                    that.inFrame = true;
                    try {
                        var check = parent._ttema;
                        if (parent._ttema) {
                            that.haveTTEMA = parent._ttema;
                        }
                        if (parent._ttsvc) {
                            that.haveTTSVC = parent._ttsvc;
                        }
                        return true;
                    }
                    catch (error) {
                        try {
                            var check = window.parent.postMessage('RequestAuthorisation', '*');
                        }
                        catch (error) {
                            return false;
                        }
                    }
                }
            },
            ReturnedAuthorisation: function(authorisationObject) {
                window.its.visualiser.common.License.haveTTEMA = authorisationObject.data._ttema;
                window.its.visualiser.common.License.haveTTSVC = authorisationObject.data._ttsvc;
            }
        },
        _blinkIcon: function (iconObject, stayOn) {
            window.its.visualiser.common.LocalLog('Executing: _blinkIcon', window.descartes, 'debug');
            var methodReturn = false;
            if (iconObject) {
                if (iconObject.classList.contains('menu-icon-blink')) {
                    iconObject.classList.remove('menu-icon-blink');
                }
                else {
                    iconObject.classList.add('menu-icon-blink');
                    if (stayOn !== true) {
                        setTimeout(window.its.visualiser.common._blinkIcon, 1000, iconObject);
                    }
                }
                methodReturn = true;
            }
            return methodReturn;
        },
        /**
         * Will Round a given number with the required precision
         * 
         * Rounding is perfomed after multiplying <i><b>parameter</b> value</i> by
         * <i><b>parameter</b> precision</i>^10. If <i><b>parameter</b> precision</i> is GT 0,
         * then 0.5 will be added (before the Round) to "force" Rounding Up
         * 
         * @param {Number} value The number to Round
         * @param {Integer} precision Number of decimal places to round to
         * @returns {Number} The Rounded number
         */
        MyRound: function(value, precision) {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, window.its.visualiser.common.descartes, 'debug');
            var multiplier = 1;
            var adjust = 0.5;
            precision = parseInt(precision);
            multiplier = Math.pow(10,precision);
            if (precision <= 0) {
                adjust = 0;
            }
            return Math.round((value * multiplier) + adjust) / multiplier;
        },
        
        HelperParseLocation: function() {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, window.its.visualiser.common.descartes, 'debug');
            var that = window.its.visualiser.common,
                result = '',
                queryString = '';
            that.useHost = location.host;
            that.useProtocol = location.protocol;
            queryString = result = location.search;
            if (queryString.length > 0) {
                result = that.RemoveSearch(queryString, 'automatic');
                result = that.RemoveSearch(result, 'manual');
                // ... add other query parameters to be removed HERE
                if (result.length !== queryString.length) {                     // Something has been removed / changed
                    if (result.length === 0) { result = '?'; }                  // there has to be something in the result
                    if (result.indexOf('&') === 0) { result = result.replace('&', '?'); }   
                    window.history.replaceState('', '', result);
                    result = '';                                                // Return this to its previous State
                }
            }
            result = that.HelperSetCodeBase(location.hostname);
            if (result === true) {
                return true;
            }
            else {
                return false;
            }
        },
        
        HelperSetCodeBase: function (hostname) {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, window.its.visualiser.common.descartes, 'debug');
            var that = window.its.visualiser.common,
                methodReturn = false,
                splitHostname = hostname.split('.');
            if (splitHostname[0] === 'its') {
                that.codeBase = '';
                that.codeName = 'production';
                that.subDomain = 'its';
                methodReturn = true;
            }
            else if (splitHostname[0] === 'its-dev') {
                that.codeBase = 'dev';
                that.codeName = 'development';
                methodReturn = true;
                that.subDomain = 'its-dev';
            }
            else if (splitHostname[0] === 'its-uat') {
                that.codeBase = 'uat';
                that.codeName = 'acceptance';
                methodReturn = true;
                that.subDomain = 'its-uat';
            }
            else {
                that.errorMessages = 'Unable to determine valid Code Base';
            }
            return methodReturn;
        },
        
        ReportError: function(errorMessage) {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, window.its.visualiser.common.descartes, 'debug');
            var reportContainer = null;
            if (errorMessage.length > 0) {
                errorMessage = errorMessage.split("\n").join("<br>");
            }
            else {
                errorMessage = 'Unknown Error';
            }
            reportContainer = document.createElement('div');
            reportContainer.setAttribute('class', 'error-report');
            reportContainer.setAttribute('onclick', 'parentNode.removeChild(this)');
            reportContainer.style.cssText = window.its.visualiser.common.errorCSS;
            reportContainer.innerHTML = window.its.visualiser.common.errorHTML;
            document.getElementById('main-container').appendChild(reportContainer);
            document.getElementById('error-message').innerHTML = errorMessage;
            document.getElementById('error-countdown').innerHTML = window.its.visualiser.common.errorTimeout;
            window.its.visualiser.common.errorTime = setTimeout(its.visualiser.common.ClearError, parseInt(window.its.visualiser.common.errorTimeout * 1000));
            window.its.visualiser.common.errorCountdown = setInterval(function() {
                var timeContainer = document.getElementById('error-countdown');
                var timeLeft = null;
                if (timeContainer) {
                    timeLeft = timeContainer.innerHTML;
                    document.getElementById('error-countdown').innerHTML = timeLeft - 1;
                    if (timeLeft < 0) {
                        clearInterval(window.its.visualiser.common.errorCountdown);
                    }
                }
                else {
                    its.visualiser.common.ClearError();
                }
            }, 1000);
            return true;
        },
        /**
         * Will remove the Error Report
         * 
         * @returns {Boolean} TRUE if there was an Error Report, FALSE otherwise.
         */
        ClearError: function() {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, window.its.visualiser.common.descartes, 'debug');
            var errorContainer = document.getElementsByClassName('error-report')[0],
                methodReturn = false;
            if (typeof(errorContainer) !== 'undefined') {
                clearInterval(window.its.visualiser.common.errorCountdown);
                errorContainer.outerHTML = '';
                methodReturn = true;
            }
            return methodReturn;
        },
        ErrorHalt: function(errorMessage) {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, window.its.visualiser.common.descartes, 'debug');
            window.its.visualiser.common.ShowAllSections('none');
            document.getElementById('update-status').innerHTML = errorMessage;
            document.getElementById('location-date').innerHTML = 'Service Unavailable';
            document.getElementsByClassName('refresh-status')[0].style.visibility = 'visible';
            return true;
        },
        ShowAdvisory: function(adviceNotice, processing) {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, window.its.visualiser.common.descartes, 'debug');
            var methodReturn = false;
            var leader = '<dt>Advisory Notice:</dt>';
            var newContent = '';
            var advisoryElement = document.getElementById('advisory-notice');
            var currentContent = null;
            if (advisoryElement) {
                currentContent = advisoryElement.innerHTML;
                if (adviceNotice.trim().length === 0) {
                    adviceNotice = 'Unknown Notice processing ' + processing ;
                }
                if ((currentContent) && (currentContent.indexOf(adviceNotice) < 0)) {
                    if (adviceNotice.indexOf('<dd') < 0) {
                        adviceNotice = '<dd>' + adviceNotice + '</dd>';
                    }
                    if (currentContent.indexOf(leader) < 0) {
                        newContent = leader + adviceNotice; 
                    }
                    else {
                        newContent = currentContent + adviceNotice;
                    }
                    document.getElementById('advisory-notice').innerHTML = newContent;
                    document.getElementById('advisory-notice').parentNode.style.display = 'block';
                    methodReturn = true;
                }
            }
            return methodReturn;
        },
        ShowAllSections: function(showMode) {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, window.its.visualiser.common.descartes, 'debug');
            var methodReturn = 0;
            var sectionList = window.its.visualiser.common.wdvSections;
            var getSection = null;
            if ((typeof(showMode) === 'undefined') || (showMode !== 'none')) {
                showMode = 'block';
            }
            else {
                showMode = 'none';
            }
            for (var i=0; i<sectionList.length; i++) {
                getSection = document.getElementById(sectionList[i]);
                if (getSection) {
                    getSection.style.display = showMode;
                    methodReturn++;
                }
            }
            if (showMode === 'block') {
                setTimeout(window.its.visualiser.common.ResizeFrame(), 3000);
            }
            return methodReturn;
        },
        ShowHide: function(targetId, controlObject) {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, window.its.visualiser.common.descartes, 'debug');
            var methodReturn = null;
            var currentState = null;
            var nextState = null;
            var usingIcon = controlObject.src;
            var currentIcon = '';
            var nextIcon = '';
            var showIcon = '';
            var hideIcon = '';
            var targetElement = document.getElementById(targetId);
            if (targetElement) {
                if ((usingIcon) && (controlObject.parentNode.dataset.showIcon) && (controlObject.parentNode.dataset.hideIcon)) {
                        showIcon = controlObject.parentNode.dataset.showIcon;
                        hideIcon = controlObject.parentNode.dataset.hideIcon;
                }
                currentState = getComputedStyle(targetElement, null).display;
                if (currentState === 'block') {
                    nextState = 'none';
                    nextIcon = showIcon;
                    currentIcon = hideIcon;
                }
                else if (currentState === 'none') {
                    nextState = 'block';
                    nextIcon = hideIcon;
                    currentIcon = showIcon;
                }
                targetElement.style.display = nextState;
                if (usingIcon) {
                    controlObject.src = usingIcon.replace(currentIcon, nextIcon);
                }
            }
            if (typeof(controlObject) === 'object') {
                window.its.visualiser.common._blinkIcon(controlObject);
            }
            return methodReturn;
        },
        ConsoleLogger: function(buttonObject) {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, window.its.visualiser.common.descartes, 'debug');
            var methodReturn = null;
            var imageSource = buttonObject.src;
            var imageAlt = buttonObject.alt;
            var currentSrc = 'lined';
            var nextSrc = 'blank';
            var currentAlt = 'Enabled';
            var nextAlt = 'Disabled';
            if (window.jsLogger !== 'absent') {
                window.its.visualiser.common.logEnabled = false;
                methodReturn = false;
                if (imageSource.indexOf('blank') > 0) {
                    currentSrc = 'blank';
                    nextSrc = 'lined';
                    currentAlt = 'Disabled';
                    nextAlt = 'Enabled';
                    window.its.visualiser.common.logEnabled = true;
                    methodReturn = true;
                }
                buttonObject.src = imageSource.replace(currentSrc, nextSrc);
                buttonObject.alt = imageAlt.replace(currentAlt, nextAlt);
            }
            return methodReturn;
        },
        LocalLog: function (message, descartes, priority) {
            var methodReturn = null;
            var logPrompt = '';
            if (typeof(descartes) === 'undefined') {
                descartes = 'UNK';
            }
            if (typeof(priority) === 'undefined') {
                priority = 'debug';
            }
            if (window.its.visualiser.common.logEnabled) {
                if (window.console) {
                    logPrompt = priority.toUpperCase() + ':::' + descartes + '/' +window.clientName + ':::';
                    if ((typeof(message) === 'object') || (typeof(message) === 'function')) {
                        console.log(logPrompt);
                        console.log(message);
                    }
                    else {
                        console.log(logPrompt + message);
                    }
                    methodReturn = true;
                }
                else {
                    alert(message);
                    methodReturn = false;
                }
            }
            return methodReturn;
        },
        /**
         * Will capitalise first letter of (<i><b>parameter</b> content</i>)
         * 
         * If <i><b>parameter</b> content</i> is not of <i><b>TYPE</b> STRING</i>, it will be returned unchanged
         * 
         * @param {string} content The text / word to capitalise
         * @returns {string} The capitalised text / word
         */
        UCFirst: function (content) {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, this.descartes, 'debug');
            var methodReturn = content;
            if (typeof(content) === 'string') {
                content.trim();
                if ((content.length > 0) && (content !== window.naText)) {
                    methodReturn = content[0].toUpperCase() + content.slice(1).toLowerCase();
                }
            }
            return methodReturn;
        },
        
        RemoveSearch: function (queryString, removeParameter) {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, window.its.visualiser.common.descartes, 'debug');
            var that = this,
                removeParameter = removeParameter + '=yes',
                methodReturn = queryString;
            if (queryString.indexOf(removeParameter) > 0) {
                queryString = queryString.replace('?' + removeParameter, '');   // if is first in chain
                queryString = queryString.replace('&' + removeParameter, '');   // if is elswhere in chain
                methodReturn = queryString;
            }
            return methodReturn;
        },
        ResizeFrame: function() {
            var myMessage = 'wdvLoaded|';                                       // @todo Add specific Client name / id
            var myContent = document.getElementById("main-container");
            var positionInfo = myContent.getBoundingClientRect();
            var myHeight = positionInfo.height;
            myHeight = parseInt(myHeight) + 20;
            try {
                window.parent.postMessage(myMessage + myHeight, '*');
                return true;
            }
            catch (error) { return false; }
        },
        
        Init: function() {
            window.its.visualiser.common.LocalLog('Executing: ' + arguments.callee.name, window.its.visualiser.common.descartes, 'debug');
            var that = window.its.visualiser.common,
                result = null,
                methodReturn = false;
            result = that.HelperParseLocation();
            if (result === true) {
                if (window.jsLogger === 'onload') {
                    that.logEnabled = true;
                    window.its.visualiser.common.ConsoleLogger(document.getElementById('log-tool').firstElementChild);
                }
                that.License.Init();
                methodReturn = true;
            }
            else {
                that.ReportError(that.errorMessage);
                methodReturn = false;
            }
            return methodReturn;
        }
    };
    /* Set a Listener for Posted Messages */
    window.addEventListener('message', window.its.visualiser.common.License.ReturnedAuthorisation, false);